package com.dossier.api.domain.catalog;

import jakarta.persistence.*;
import java.io.Serializable;
import java.time.Instant;

/**
 * One immutable-once-published version of a plan (docs/subscriptions/08-data-model.md section 3): the intervals it is sold at, its AI budget cap, the
 * base product whose prices are the plan's base prices (NULL for FREE) and, for an organization plan, the seat rules. A subscription points at the
 * version it bought, so a later version never changes what an existing subscriber has. {@code liveKey} is generated by MySQL (non-NULL only while
 * PUBLISHED, UNIQUE): one live version per plan. Platform data, no org_id.
 */
@Entity
@Table(name = "plan_version")
public class PlanVersion implements Serializable {

    private static final long serialVersionUID = 1L;

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "id", nullable = false)
    private Long id;

    @Column(name = "plan_id", nullable = false)
    private Long planId;

    @Column(name = "version", nullable = false)
    private Integer version;

    @Column(name = "status", length = 12, nullable = false)
    private String status = "DRAFT";

    @Column(name = "effective_from")
    private Instant effectiveFrom;

    @Column(name = "effective_until")
    private Instant effectiveUntil;

    @Column(name = "catalog_version")
    private Integer catalogVersion;

    @Column(name = "base_product_id")
    private Long baseProductId;

    @Column(name = "intervals_json", columnDefinition = "json", nullable = false)
    private String intervalsJson = "[]";

    @Column(name = "annual_discount_bp")
    private Integer annualDiscountBp;

    @Column(name = "ai_budget_cap_cents", nullable = false)
    private Integer aiBudgetCapCents = 0;

    @Column(name = "seat_rules_json", columnDefinition = "json")
    private String seatRulesJson;

    @Column(name = "presets_json", columnDefinition = "json")
    private String presetsJson;

    @Column(name = "snapshot_json", columnDefinition = "json")
    private String snapshotJson;

    @Column(name = "snapshot_hash", length = 64, columnDefinition = "char(64)")
    private String snapshotHash;

    @Column(name = "summary", length = 2000)
    private String summary;

    /** Explicit whole-period AI budgets per interval, a JSON object such as {"QUARTER":800}; an interval not listed uses cap x factor (decision E-2). */
    @Column(name = "ai_window_json", columnDefinition = "json")
    private String aiWindowJson;

    /** The Idempotency-Key the version was published with: a replay of the same key answers with the same version. */
    @Column(name = "publish_key", length = 64)
    private String publishKey;

    /** Generated by MySQL; never written from here. */
    @Column(name = "live_key", insertable = false, updatable = false)
    private Long liveKey;

    @Column(name = "published_at")
    private Instant publishedAt;

    @Column(name = "published_by", length = 50)
    private String publishedBy;

    @Column(name = "created_at", nullable = false)
    private Instant createdAt = Instant.now();

    @Column(name = "created_by", length = 50, nullable = false)
    private String createdBy;

    @Column(name = "updated_at", nullable = false)
    private Instant updatedAt = Instant.now();

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public Long getPlanId() { return planId; }
    public void setPlanId(Long planId) { this.planId = planId; }
    public Integer getVersion() { return version; }
    public void setVersion(Integer version) { this.version = version; }
    public String getStatus() { return status; }
    public void setStatus(String status) { this.status = status; }
    public Instant getEffectiveFrom() { return effectiveFrom; }
    public void setEffectiveFrom(Instant effectiveFrom) { this.effectiveFrom = effectiveFrom; }
    public Instant getEffectiveUntil() { return effectiveUntil; }
    public void setEffectiveUntil(Instant effectiveUntil) { this.effectiveUntil = effectiveUntil; }
    public Integer getCatalogVersion() { return catalogVersion; }
    public void setCatalogVersion(Integer catalogVersion) { this.catalogVersion = catalogVersion; }
    public Long getBaseProductId() { return baseProductId; }
    public void setBaseProductId(Long baseProductId) { this.baseProductId = baseProductId; }
    public String getIntervalsJson() { return intervalsJson; }
    public void setIntervalsJson(String intervalsJson) { this.intervalsJson = intervalsJson; }
    public Integer getAnnualDiscountBp() { return annualDiscountBp; }
    public void setAnnualDiscountBp(Integer annualDiscountBp) { this.annualDiscountBp = annualDiscountBp; }
    public Integer getAiBudgetCapCents() { return aiBudgetCapCents; }
    public void setAiBudgetCapCents(Integer aiBudgetCapCents) { this.aiBudgetCapCents = aiBudgetCapCents; }
    public String getSeatRulesJson() { return seatRulesJson; }
    public void setSeatRulesJson(String seatRulesJson) { this.seatRulesJson = seatRulesJson; }
    public String getPresetsJson() { return presetsJson; }
    public void setPresetsJson(String presetsJson) { this.presetsJson = presetsJson; }
    public String getSnapshotJson() { return snapshotJson; }
    public void setSnapshotJson(String snapshotJson) { this.snapshotJson = snapshotJson; }
    public String getSnapshotHash() { return snapshotHash; }
    public void setSnapshotHash(String snapshotHash) { this.snapshotHash = snapshotHash; }
    public String getAiWindowJson() { return aiWindowJson; }
    public void setAiWindowJson(String aiWindowJson) { this.aiWindowJson = aiWindowJson; }
    public String getPublishKey() { return publishKey; }
    public void setPublishKey(String publishKey) { this.publishKey = publishKey; }
    public String getSummary() { return summary; }
    public void setSummary(String summary) { this.summary = summary; }
    public Long getLiveKey() { return liveKey; }
    public Instant getPublishedAt() { return publishedAt; }
    public void setPublishedAt(Instant publishedAt) { this.publishedAt = publishedAt; }
    public String getPublishedBy() { return publishedBy; }
    public void setPublishedBy(String publishedBy) { this.publishedBy = publishedBy; }
    public Instant getCreatedAt() { return createdAt; }
    public void setCreatedAt(Instant createdAt) { this.createdAt = createdAt; }
    public String getCreatedBy() { return createdBy; }
    public void setCreatedBy(String createdBy) { this.createdBy = createdBy; }
    public Instant getUpdatedAt() { return updatedAt; }
    public void setUpdatedAt(Instant updatedAt) { this.updatedAt = updatedAt; }
}
